import{_ as a,c as o,o as e,ae as t}from"./chunks/framework.BvcDoAct.js";const c=JSON.parse(`{"title":"05 JUNON'S STORY","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/RockInOnJapan_BF/5_JUNON.md","filePath":"zh-cn/RockInOnJapan_BF/5_JUNON.md"}`),S={name:"zh-cn/RockInOnJapan_BF/5_JUNON.md"};function n(B,p,r,T,E,R){return e(),o("div",null,[...p[0]||(p[0]=[t('<h1 id="_05-junon-s-story" tabindex="-1">05 JUNON&#39;S STORY <a class="header-anchor" href="#_05-junon-s-story" aria-label="Permalink to &quot;05 JUNON&#39;S STORY&quot;">​</a></h1><h2 id="敲响聆听者心门的歌声-其源头所在。绝不放弃-但始终保持自然本色。" tabindex="-1">敲响聆听者心门的歌声，其源头所在。绝不放弃，但始终保持自然本色。 <a class="header-anchor" href="#敲响聆听者心门的歌声-其源头所在。绝不放弃-但始终保持自然本色。" aria-label="Permalink to &quot;敲响聆听者心门的歌声，其源头所在。绝不放弃，但始终保持自然本色。&quot;">​</a></h2><p>● BE:FIRST已经进入第5年了，有什么样的感慨吗？</p><p>“回过头来看，感觉人生也不过才活了两年，却没有哪四年像这四年一样，在一年之中塞满了这么多事情。但比起这些，我更强烈的感受是，从出道至今，我们始终如一地、真诚地面对音乐。”</p><p>● 最佳专辑也已经发行了，在这段高密度的时间里，你如何看待自己在唱歌和舞蹈上的变化？</p><p>“从团体音乐的角度来说，在《Boom Boom Back》发布之后，我们一起讨论过，也开始能够参与到歌曲制作中来。在巡演的过程中，我们一边思考‘需要什么样的歌曲’、‘拥有什么样的作品能让现场更好’，一边推进创作。正如出道时所说的‘无类型限制’，我们在不断接触各种风格的同时，也逐渐能更深入地触及音乐本质。至于个人方面，舞蹈是从参加选秀时才正式开始的，走到现在这4年，也算积累了一定的实力。唱歌方面，虽然原本就喜欢，但并不是一边跳一边唱的类型，在适应唱跳的过程中，我也逐渐找到了适合这种形式的唱法。”</p><p>● BE:FIRST没有队长也没有固定中心。所以不同时期、不同现场，观众的目光会落在不同成员身上，会有一种“现在轮到这个人了”的感觉。而我个人觉得，现在好像是JUNON的回合。在「BMSG FES&#39;25」上你的表现非常亮眼。</p><p>“谢谢。从世界巡演回来之后……虽然很难用语言说明，但感觉像是突破了一层什么。在『BMSG FES』上，我觉得自己比以往更放得开了。”</p><p>● 这次的最佳专辑中收录了新曲《Stay Strong》。这首歌是你出演的电影《WIND BREAKER》的主题曲，而且你也参与了作词。包括出演电影这个挑战在内，创作动机应该和以往有所不同吧？</p><p>“能够参与电影拍摄，也反复阅读剧本再进行作词，这点让我很庆幸。在电影宣传现场，也有人对我说‘这首歌真的很好听’。在拍摄过程中，我想把导演所重视的东西、自己亲眼看到的内容，甚至是剧本中没有写出来的部分，也通过歌词稍微表达出来，所以提出了很多词句的想法。而且不仅是我写的部分，社长也把我的词融入到了其他段落里。我觉得这是一首在观影之后还能进一步加深电影魅力的歌曲。”</p><p>● 演戏本身感觉如何？</p><p>“很难。因为是漫画改编，把二维变成三维，所以有种稍微脱离现实的感觉。我饰演的杉下京太郎是被称为‘狂犬’的角色，导演也要求我‘像野兽一样存在’，所以和日常的自己相差很远。无论是站姿还是表现方式，他话也不多，这样的表演确实很难，但也是一次很好的经验。”</p><p>● 这些经验也融入到了《Stay Strong》中。我觉得这首歌里你的歌声非常有力量、非常震撼。本来JUNON的声音就是BE:FIRST的重要武器，现在感觉更加打磨过了。</p><p>“这一点我自己其实没太多感觉。并没有刻意想着‘去改变’，当然会想着去提升，但变化好像没有那么明显的自觉。”</p><blockquote><p>有一个不像任何成员性格的「BE:FIRST」人格。带点调皮，精通音乐，也非常享受现场。</p></blockquote><p>● 在2023年的个人采访中，你曾说过“唱歌就像穿上动力装甲”。现在感觉这个“装甲”更强了，还装备了各种武器和工具，能做到的事情也更多了。</p><p>“能做到的事情确实变多了，也更从容了。在这4年的经验中尝试了很多，也找到了适合自己和不适合自己的方式。”</p><p>● 当时你还说过“如果不能唱好，就不想站上舞台”。但仔细想想，站在舞台上本来就很紧张，再加上还要唱歌，按理说应该更紧张才对。</p><p>“是这样吗？”</p><p>● 但你是相反的。</p><p>“对我来说，唱歌反而更轻松。单纯站着说话才更紧张。从小我就不太喜欢站在人前，所以才没有一开始就走上当艺人的路。现在也是，在舞台上说话还是会很紧张。但在BE:FIRST的演出里就没那么紧张。”</p><p>● 也就是说，“唱歌”这个行为本身让你更自在。是不是因为对歌声有绝对的自信？</p><p>“比起出道时，现在肯定更有自信。随着经验积累，自信也慢慢建立起来了。”</p><p>● 那舞蹈呢？</p><p>“舞蹈的话还远远不够。不过也看类型。BE:FIRST风格的歌曲会比较容易，但如果是我们还没接触过的舞种，就会觉得困难。对我来说，歌是‘动力装甲’，但舞蹈不是。所以如果只是单纯跳舞，感觉完全不一样。”</p><p>● 但只要有唱歌就没问题？</p><p>“没问题。”</p><p>● 也就是说，在你心中，歌声始终是最核心的武器。在BE:FIRST中表达时，你如何看待自己的声音所起到的作用？</p><p>“有人跟我说过，比如在街上听到《Bye-Good-Bye》，副歌开头我的声音一出来就会‘一下子被吸引住’。如果能唱出让不认识BE:FIRST的人也产生兴趣的歌，那就很好了，所以听到这种反馈我会很开心。”</p><p>● 你其实不太会表现出自己很努力的样子。</p><p>“因为我自己也觉得没那么‘努力’（笑）。没有特别去做声乐训练，舞蹈也是因为有很多实战机会，所以慢慢提升了。在录音或演出前会思考唱法，所以是在实战中成长的。”</p><p>● 那么在BE:FIRST这个整体中，你觉得自己的表达方式有怎样的进化？</p><p>“比起出道时，在现场传达情感的方式变得更强烈了。我们对现场的热情非常高，平时大家都会说‘好想演出’，甚至会说‘不演出就会枯萎’。正因为对现场的渴望，我们更想把音乐好好传递出去。这种心情越来越强。我个人也是最享受现场。”</p><p>● 为什么会这样？</p><p>“为什么呢？创作也很喜欢，但把作品带到舞台上表演是最开心的。不只是自己开心，也能看到观众开心。而且那是一个可以用身体去感受一切的地方，所以是我最喜欢的地方。”</p><p>● 一开始就是这样吗？</p><p>“一开始完全不是。以前紧张感占据了很大部分，是慢慢才喜欢上的。最早的粉丝见面会每天都很紧张。大概是在第一次Hall巡演中逐渐改变的，还有各种音乐节。”</p><p>● 从最初紧张的粉丝见面会，到现在能完成世界巡演，你刚刚说“在世界巡演中突破了一层”，那实际去了之后有什么感受？</p><p>“真的像是不可思议的景象。我们是为了把音乐带给世界而去的，但不知道到底是什么传达到了——在不知道大家是怎么认识我们的情况下，现场却聚集了这么多人，让我既开心又震惊。比如在美国，我们和ATEEZ有合作，也参与了他们的演出，可能因此有更多曝光机会。但像欧洲那边，真的很不可思议。”</p><p>● 而且BE:FIRST主要用日语创作，居然也能传达出去，这本身就很有意思。</p><p>“是的。不过我听欧美音乐时，也不会完全理解歌词。更多是因为编曲好、节奏好、氛围好……可能是那些超越语言的东西打动了大家。”</p><p>● 那种“氛围”的部分，也就是非语言的BE:FIRST特质，确实越来越明显了。</p><p>“从《Mainstream》开始参与制作后，我自己也对创作产生了很大兴趣。这样一来，听音乐的方式也改变了，现场的乐趣也增加了。所以会更想演出，这次粉丝见面会也是还没开始就很期待。随着自己的想法更多融入作品，对表演的情感也变得更强了。”</p><p>● 原本就有“想在现场直接传达”的愿望，再加上作品中也越来越多体现你们自身，这种叠加让BE:FIRST的表演更强了。这一两年的现场明显更有生命力。</p><p>“我也这么觉得。我们每次演出结束后都会看回放，现在的演出连自己看都觉得很享受。以前是抱着学习的心态看，现在可以当作娱乐来享受。我们为了现场而创作的歌曲越来越多进入歌单，也让表演更有期待，也很想早点让大家听到。”</p><blockquote><p>我一直觉得只要去做就能做到。就算这次不行，下次也可能行。也许不能一次成功，但只要不放弃就一定能做到。</p></blockquote><p>● 与此同时，曲风的跨度也越来越大。在这种情况下，你觉得现在让BE:FIRST成为BE:FIRST的核心是什么？</p><p>“嗯……首先是关系很好吧。成员之间的关系自然会反映在音乐和舞蹈中，观众也能感受到。社长常说‘BE:FIRST像是有一个独立的人格’，我也很认同。那种不像任何成员的‘BE:FIRST人格’，有点调皮，很懂音乐，也很期待现场……正因为有这个人格……呃，我好像不知道怎么收尾了（笑）”</p><p>● 的确有这样一个人格，而且是花时间慢慢培养出来的。现在也能感觉到它逐渐成型了。</p><p>“是的。”</p><p>● 作为前提，你曾说过“希望成为一个能让大家都做自己的人”。现在怎么看？</p><p>“现在大家已经都能自然做自己了，所以没有特别去想这个。我自己也是，而且自由度更高了。不管是参与创作，还是在舞台上或私下，都能保持真实的自己。”</p><p>● 那对你来说，“做自己”是什么状态？</p><p>“能把想说的说出来吧。大家讨论时，各自发表意见，然后像LEO那样的人会做总结推动。我则更倾向于全部都试一遍，从中找到最合适的。不是否定任何意见，而是通过结果来判断。相比情绪，我更偏逻辑地表达自己的想法。”</p><p>● 你以前也说过“不会否定去尝试这件事”。</p><p>“对，因为不试就不知道。而且我觉得只要去做就能做到。就算这次不行，下次也可能行。也许不能一次成功，但只要不放弃就一定能做到。”</p><p>● BE:FIRST的发展也是这样。不断尝试以前没做过的事情，最终积累出压倒性的成果。比如你去演戏也是一样。</p><p>“是的。不过演戏让我觉得难的一点是，就算自己想再来一次，只要导演说OK就不能重来。可能是通过不断拍摄积累经验，才能慢慢成长吧。”</p><p>● 你当初参加《THE FIRST》也是抱着“试试看就能做到”的心态，而且确实做到了。有这个基础，才能不断积累。</p><p>“嗯，是的。”</p><p>● 这次采访所有成员让我很感动的一点是，虽然大家都有成长和变化，但那个“基础”一直没有动摇。感觉是在一条很笔直的路上前进。</p><p>“我没特别想过这些，但因为一直都是真心在说话，所以方向不会突然改变。”</p><p>● 还有一点是，BE:FIRST从不被环境或舆论左右，一直保持“我们就是我们”的姿态。</p><p>“我觉得只要有目标和梦想，当你最终到达的时候，就会发现‘其实一直没有偏离’。很幸运，我们一直在实现目标。虽然花了时间，但4年内完成了巨蛋巡演和世界巡演，真的很感激。”</p><p>● 虽然还在途中，但至少当初设定的目标已经实现了一部分。对此会有成就感吗？</p><p>“当然有。关于‘走向世界’，不能说做了世界巡演就完成了，这还有很长的路。但2024年首次站上东京巨蛋、之后完成巨蛋巡演，这些都让我很有成就感。不过这些也是因为很多人支持我们才实现的。我们只是专注做好表演、做好音乐，非常感谢为我们铺路的社长和工作人员。”</p><p>● 接下来就需要你们自己去铺路，甚至走出既有轨道，开辟新道路了。</p><p>“是的。到世界巡演为止，我们是在既有轨道上全力奔跑。但回头看‘走向世界’这个目标，现在反而像是轨道消失了。今后无论是‘想在哪演出’还是‘想获得什么奖项’，无论个人还是团体，都有新的课题。感觉轨道变成了多条分支，每个人都要在各自的轨道上前进。”</p><p>● 那你个人的轨道，目标在哪里？</p><p>“我个人的话……想在海外的足球场开演唱会。”</p><p>● 比如温布利球场？</p><p>“对，比如英国之类的。有很多这样的目标。所以一切才刚开始，后面的路会更长。”</p><p>● 在「BMSG FES」上，BE:FIRST的表现非常震撼，也能感受到你们背负BMSG的觉悟。随着后辈越来越多，你作为年长成员，会感到责任吗？</p><p>“后辈确实多了，所以会觉得作为BMSG的一员、作为BE:FIRST，要展现帅气的背影。今年尤其明显，新增了HANA和STARGLOW两个团体。相比去年只有我们和MAZZEL，确实更有‘前辈感’了。”</p><p>● 你们的表现确实像是在用背影引领。</p><p>“后辈中也有和我们同期进入事务所的人，还有一起努力过的人。所以不是那种‘必须带领他们’的上位视角，而是觉得多了很多很好的伙伴。不过因为我们先出道，还是希望能展现一个帅气的背影。”</p>',76)])])}const F=a(S,[["render",n]]);export{c as __pageData,F as default};
